14	#include "cache_cluster.h"
15	
16	using namespace vortex;
17	
18	CacheCluster::CacheCluster(const SimContext& ctx,
19	                           const char* name,
20	                           uint32_t num_inputs,
21	                           uint32_t num_units,
22	                           const Cache::Config& cache_config)
23		: SimObject(ctx, name)
24		, core_req_in(num_inputs, std::vector<SimChannel<MemReq>>(cache_config.num_inputs, this))
25		, core_rsp_out(num_inputs, std::vector<SimChannel<MemRsp>>(cache_config.num_inputs, this))
26		, mem_req_out(cache_config.mem_ports, this)
27		, mem_rsp_in(cache_config.mem_ports, this)
28		, caches_(__MAX(num_units, 0x1))
29	{
30		Cache::Config cache_config2(cache_config);
31		if (0 == num_units) {
32			num_units = 1;
33			cache_config2.bypass = true;
34		}
35	
36		char sname[100];
37	
38		// Arbitrate incoming core interfaces
39		std::vector<MemArbiter::Ptr> input_arbs(cache_config.num_inputs);
40		for (uint32_t i = 0; i < cache_config.num_inputs; ++i) {
41			snprintf(sname, 100, "%s-input-arb%d", name, i);
42			input_arbs.at(i) = MemArbiter::Create(sname, ArbiterType::RoundRobin, num_inputs, num_units);
43			for (uint32_t j = 0; j < num_inputs; ++j) {
44				this->core_req_in.at(j).at(i).bind(&input_arbs.at(i)->ReqIn.at(j));
45				input_arbs.at(i)->RspOut.at(j).bind(&this->core_rsp_out.at(j).at(i));
46			}
47		}
48	
49		// Arbitrate outgoing memory interfaces
50		std::vector<MemArbiter::Ptr> mem_arbs(cache_config.mem_ports);
51		for (uint32_t i = 0; i < cache_config.mem_ports; ++i) {
52			snprintf(sname, 100, "%s-mem-arb%d", name, i);
53			mem_arbs.at(i) = MemArbiter::Create(sname, ArbiterType::RoundRobin, num_units, 1);
54			mem_arbs.at(i)->ReqOut.at(0).bind(&this->mem_req_out.at(i));
55			this->mem_rsp_in.at(i).bind(&mem_arbs.at(i)->RspIn.at(0));
56		}
57	
58		// Connect caches
59		for (uint32_t i = 0; i < num_units; ++i) {
60			snprintf(sname, 100, "%s%d", name, i);
61			caches_.at(i) = Cache::Create(sname, cache_config2);
62	
63			for (uint32_t j = 0; j < cache_config.num_inputs; ++j) {
64				input_arbs.at(j)->ReqOut.at(i).bind(&caches_.at(i)->core_req_in.at(j));
65				caches_.at(i)->core_rsp_out.at(j).bind(&input_arbs.at(j)->RspIn.at(i));
66			}
67	
68			for (uint32_t j = 0; j < cache_config.mem_ports; ++j) {
69				caches_.at(i)->mem_req_out.at(j).bind(&mem_arbs.at(j)->ReqIn.at(i));
70				mem_arbs.at(j)->RspOut.at(i).bind(&caches_.at(i)->mem_rsp_in.at(j));
71			}
72		}
73	}
74	
75	CacheCluster::~CacheCluster() {}
76	
77	Cache::PerfStats CacheCluster::perf_stats() const {
78		Cache::PerfStats perf;
79		for (auto cache : caches_) {
80			perf += cache->perf_stats();
81		}
82		return perf;
83	}
