14	#include "socket.h"
15	#include "cache_cluster.h"
16	#include "core.h"
17	#include "cluster.h"
18	#include "constants.h"
19	
20	using namespace vortex;
21	
22	class Socket::Impl {
23	public:
24	  Impl(Socket* simobject)
25	    : simobject_(simobject)
26	    , cores_(VX_CFG_SOCKET_SIZE)
27	  {
28	    auto cores_per_socket = cores_.size();
29	
30	    const std::string& name = simobject->name();
31	    char sname[100];
32	
33	    snprintf(sname, 100, "%s-icache", name.c_str());
34	    icaches_ = CacheCluster::Create(sname, cores_per_socket, VX_CFG_NUM_ICACHES, Cache::Config{
35	      !VX_CFG_ICACHE_ENABLED,
36	      log2ceil(VX_CFG_ICACHE_SIZE),  // C
37	      log2ceil(VX_CFG_L1_LINE_SIZE), // L
38	      log2ceil(VX_CFG_L1_LINE_SIZE), // S (no sectoring)
39	      log2ceil(sizeof(uint32_t)), // W
40	      log2ceil(VX_CFG_ICACHE_NUM_WAYS),// A
41	      log2ceil(1),            // B
42	      VX_CFG_XLEN,                   // address bits
43	      1,                      // number of inputs
44	      VX_CFG_ICACHE_MEM_PORTS,       // memory ports
45	      false,                  // write-back
46	      false,                  // write response
47	      VX_CFG_ICACHE_MSHR_SIZE,       // mshr size
48	      VX_CFG_ICACHE_LATENCY,         // pipeline latency (capacity-scaled, matches RTL)
49	      VX_CFG_ICACHE_REPL_POLICY,     // replacement policy
50	      false,                  // is_llc (icache never carries AMO state)
51	    });
52	
53	    snprintf(sname, 100, "%s-dcache", name.c_str());
54	    // L1 dcache is the LLC iff neither L2 nor L3 is enabled.
55	    dcaches_ = CacheCluster::Create(sname, cores_per_socket, VX_CFG_NUM_DCACHES, Cache::Config{
56	      !VX_CFG_DCACHE_ENABLED,
57	      log2ceil(VX_CFG_DCACHE_SIZE),  // C
58	      log2ceil(VX_CFG_DCACHE_LINE_SIZE), // L
59	      log2ceil(VX_CFG_DCACHE_SECTOR_SIZE), // S
60	      log2ceil(DCACHE_WORD_SIZE), // W
61	      log2ceil(VX_CFG_DCACHE_NUM_WAYS),// A
62	      log2ceil(VX_CFG_DCACHE_NUM_BANKS), // B
63	      VX_CFG_XLEN,                   // address bits
64	      VX_CFG_DCACHE_NUM_REQS,        // number of inputs
65	      VX_CFG_L1_MEM_PORTS,           // memory ports
66	      VX_CFG_DCACHE_WRITEBACK,       // write-back
67	      false,                  // write response
68	      VX_CFG_DCACHE_MSHR_SIZE,       // mshr size
69	      VX_CFG_DCACHE_LATENCY,         // pipeline latency (capacity-scaled, matches RTL)
70	      VX_CFG_DCACHE_REPL_POLICY,     // replacement policy
71	      (VX_CFG_DCACHE_ENABLED != 0) && (VX_CFG_L2_ENABLED == 0) && (VX_CFG_L3_ENABLED == 0), // is_llc
72	    });
73	
74	    // find overlap
75	    uint32_t overlap = __MIN(VX_CFG_ICACHE_MEM_PORTS, VX_CFG_L1_MEM_PORTS);
76	
77	    // connect l1 caches to outgoing memory interfaces
78	    for (uint32_t i = 0; i < VX_CFG_L1_MEM_PORTS; ++i) {
79	      snprintf(sname, 100, "%s-l1_arb%d", name.c_str(), i);
80	      auto l1_arb = MemArbiter::Create(sname, ArbiterType::RoundRobin, 2 * overlap, overlap);
81	
82	      if (i < overlap) {
83	        icaches_->mem_req_out.at(i).bind(&l1_arb->ReqIn.at(i));
84	        l1_arb->RspOut.at(i).bind(&icaches_->mem_rsp_in.at(i));
85	
86	        dcaches_->mem_req_out.at(i).bind(&l1_arb->ReqIn.at(overlap + i));
87	        l1_arb->RspOut.at(overlap + i).bind(&dcaches_->mem_rsp_in.at(i));
88	
89	        l1_arb->ReqOut.at(i).bind(&simobject->mem_req_out.at(i));
90	        simobject->mem_rsp_in.at(i).bind(&l1_arb->RspIn.at(i));
91	      } else {
92	        if (VX_CFG_L1_MEM_PORTS > VX_CFG_ICACHE_MEM_PORTS) {
93	          // if more dcache ports
94	          dcaches_->mem_req_out.at(i).bind(&simobject->mem_req_out.at(i));
95	          simobject->mem_rsp_in.at(i).bind(&dcaches_->mem_rsp_in.at(i));
96	        } else {
97	          // if more icache ports
98	          icaches_->mem_req_out.at(i).bind(&simobject->mem_req_out.at(i));
99	          simobject->mem_rsp_in.at(i).bind(&icaches_->mem_rsp_in.at(i));
100	        }
101	      }
102	    }
103	
104	    // create cores
105	    for (uint32_t i = 0; i < cores_per_socket; ++i) {
106	      uint32_t core_id = simobject_->id() * cores_per_socket + i;
107	      snprintf(sname, 100, "%s-core%d", name.c_str(), i);
108	      cores_.at(i) = Core::Create(sname, core_id, simobject_);
109	    }
110	
111	    // connect cores to caches
112	    for (uint32_t i = 0; i < cores_per_socket; ++i) {
113	        cores_.at(i)->icache_req_out.at(0).bind(&icaches_->core_req_in.at(i).at(0));
114	        icaches_->core_rsp_out.at(i).at(0).bind(&cores_.at(i)->icache_rsp_in.at(0));
115	
116	      for (uint32_t j = 0; j < VX_CFG_DCACHE_NUM_REQS; ++j) {
117	        cores_.at(i)->dcache_req_out.at(j).bind(&dcaches_->core_req_in.at(i).at(j));
118	        dcaches_->core_rsp_out.at(i).at(j).bind(&cores_.at(i)->dcache_rsp_in.at(j));
119	      }
120	    }
121	  }
122	
123	  bool running() const {
124	    for (auto& core : cores_) {
125	      if (core->running())
126	        return true;
127	    }
128	    return false;
129	  }
130	
131	  int get_exitcode() const {
132	    int exitcode = 0;
133	    for (auto& core : cores_) {
134	      exitcode |= core->get_exitcode();
135	    }
136	    return exitcode;
137	  }
138	
139	  void global_barrier_arrive(uint32_t bar_id, uint32_t count, uint32_t core_id) {
140	    simobject_->cluster()->global_barrier_arrive(bar_id, count, core_id);
141	  }
142	
143	  void global_barrier_resume(uint32_t bar_id, uint32_t core_index) {
144	    cores_.at(core_index)->global_barrier_resume(bar_id);
145	  }
146	
147	  Socket::PerfStats perf_stats() const {
148	    Socket::PerfStats perf_stats;
149	    perf_stats.icache = icaches_->perf_stats();
150	    perf_stats.dcache = dcaches_->perf_stats();
151	    return perf_stats;
152	  }
153	
154	  int dcr_write(uint32_t addr, uint32_t value) {
155	    for (auto& core : cores_) {
156	      int ret = core->dcr_write(addr, value);
157	      if (ret != 0)
158	        return ret;
159	    }
160	    return 0;
161	  }
162	
163	  int dcr_read(uint32_t addr, uint32_t tag, uint32_t* value) {
164	    for (auto& core : cores_) {
165	      uint16_t core_id = tag & 0xfffff;
166	      if (core_id != core->id())
167	        continue; // skip cores that don't match the tag
168	      uint32_t tag_value = tag >> 16;
169	      int ret = core->dcr_read(addr, tag_value, value);
170	      if (ret != 0)
171	        return ret;
172	    }
173	    return 0;
174	  }
175	
176	  Core::Ptr& core(uint32_t idx) {
177	    return cores_.at(idx);
178	  }
179	
180	  void dcache_flush_begin() { dcaches_->flush_begin(); }
181	  bool dcache_flush_done() const { return dcaches_->flush_done(); }
182	  void icache_flush_begin() { icaches_->flush_begin(); }
183	  bool icache_flush_done() const { return icaches_->flush_done(); }
184	
185	private:
186	  Socket*                 simobject_;
187	  std::vector<Core::Ptr>  cores_;
188	  CacheCluster::Ptr       icaches_;
189	  CacheCluster::Ptr       dcaches_;
190	};
191	
192	///////////////////////////////////////////////////////////////////////////////
193	
194	Socket::Socket(const SimContext& ctx,
195	                const char* name,
196	                uint32_t socket_id,
197	                Cluster* cluster)
198	  : SimObject(ctx, name)
199	  , mem_req_out(VX_CFG_L1_MEM_PORTS, this)
200	  , mem_rsp_in(VX_CFG_L1_MEM_PORTS, this)
201	  , socket_id_(socket_id)
202	  , cluster_(cluster)
203	  , impl_(new Impl(this))
204	{}
205	
206	Socket::~Socket() {
207	  delete impl_;
208	}
209	
210	void Socket::on_reset() {
211	  // Cores are SimObjects; reset by SimPlatform.
212	}
213	
214	void Socket::on_tick() {
215	}
216	
217	bool Socket::running() const {
218	  return impl_->running();
219	}
220	
221	int Socket::get_exitcode() const {
222	  return impl_->get_exitcode();
223	}
224	
225	void Socket::global_barrier_arrive(uint32_t bar_id, uint32_t count, uint32_t core_id) {
226	  impl_->global_barrier_arrive(bar_id, count, core_id);
227	}
228	
229	void Socket::global_barrier_resume(uint32_t bar_id, uint32_t core_index) {
230	  impl_->global_barrier_resume(bar_id, core_index);
231	}
232	
233	Socket::PerfStats Socket::perf_stats() const {
234	  return impl_->perf_stats();
235	}
236	
237	int Socket::dcr_write(uint32_t addr, uint32_t value) {
238	  return impl_->dcr_write(addr, value);
239	}
240	
241	int Socket::dcr_read(uint32_t addr, uint32_t tag, uint32_t* value) {
242	  return impl_->dcr_read(addr, tag, value);
243	}
244	
245	Core::Ptr& Socket::core(uint32_t idx) {
246	  return impl_->core(idx);
247	}
248	
249	void Socket::dcache_flush_begin() {
250	  impl_->dcache_flush_begin();
251	}
252	
253	bool Socket::dcache_flush_done() const {
254	  return impl_->dcache_flush_done();
255	}
256	
257	void Socket::icache_flush_begin() {
258	  impl_->icache_flush_begin();
259	}
260	
261	bool Socket::icache_flush_done() const {
262	  return impl_->icache_flush_done();
263	}
