43			char sname[100];
44			snprintf(sname, 100, "%s-xbar", simobject->name().c_str());
45			uint32_t lg2_line_size = log2ceil(config_.line_size);
46			uint32_t num_banks = 1 << config.B;
47			mem_xbar_ = MemCrossBar::Create(sname, ArbiterType::Priority, config.num_reqs, num_banks,
48			 [lg2_line_size, num_banks](const MemCrossBar::ReqType& req) {
49	    	// Custom logic to calculate the output index using bank interleaving
50				return (uint32_t)((req.addr >> lg2_line_size) & (num_banks-1));
51			});
