68				auto& xbar_req_out = mem_xbar_->ReqOut.at(i);
69				if (xbar_req_out.empty())
70					continue;
71	
72				auto& bank_req = xbar_req_out.peek();
73	
74				// Apply byte-enabled writes from TLM payload to local RAM.
75				if (bank_req.is_write() && bank_req.data) {
76					uint64_t line_addr = to_local_addr(bank_req.addr) & ~uint64_t(VX_CFG_MEM_BLOCK_SIZE - 1);
77					for (uint32_t b = 0; b < VX_CFG_MEM_BLOCK_SIZE; ++b) {
78						if (bank_req.byteen & (1ull << b)) {
79							uint8_t value = (*bank_req.data)[b];
80							ram_.write(&value, line_addr + b, 1);
81						}
82					}
83				}
84	
85				// Loads always respond. Stores respond when configured globally OR
86				// the request opts in via MEM_FLAG_STRSP.
87				if (!bank_req.is_write() || config_.write_reponse || bank_req.flags.strsp) {
88					// send xbar response — for reads, capture the line payload.
89					MemRsp bank_rsp{bank_req.tag, bank_req.hart_id, bank_req.uuid};
90					if (!bank_req.is_write()) {
91						auto rsp_data = make_mem_block();
92						uint64_t line_addr = to_local_addr(bank_req.addr) & ~uint64_t(VX_CFG_MEM_BLOCK_SIZE - 1);
93						ram_.read(rsp_data->data(), line_addr, VX_CFG_MEM_BLOCK_SIZE);
94						bank_rsp.data = rsp_data;
95					}
