23	static void simx_print_backtrace() {
24	  void* addrs[64];
25	  int count = ::backtrace(addrs, int(std::size(addrs)));
26	  char** symbols = ::backtrace_symbols(addrs, count);
27	  if (symbols == nullptr)
28	    return;
29	  std::cerr << "Backtrace (" << count << " frames):" << std::endl;
30	  for (int i = 0; i < count; ++i) {
31	    std::cerr << "  " << symbols[i] << std::endl;
32	  }
