36	ProcessorImpl::ProcessorImpl()
37	  : clusters_(VX_CFG_NUM_CLUSTERS)
38	{
39	  SimPlatform::instance().initialize();
40	
41		assert(VX_CFG_PLATFORM_MEMORY_DATA_SIZE == VX_CFG_MEM_BLOCK_SIZE);
42	
43	  // create kernel management unit (SimObject)
44	  kmu_ = Kmu::Create("kmu");
45	
46	  // create memory simulator
47	  memsim_ = Memory::Create("dram", Memory::Config{
48	    VX_CFG_PLATFORM_MEMORY_NUM_BANKS,
49	    VX_CFG_L3_MEM_PORTS,
50	    VX_CFG_MEM_BLOCK_SIZE,
51	    MEM_CLOCK_RATIO
52	  });
53	
54	  char sname[100];
55	
56	  // create clusters
57	  for (uint32_t i = 0; i < VX_CFG_NUM_CLUSTERS; ++i) {
58	    snprintf(sname, 100, "cluster%d", i);
59	    clusters_.at(i) = Cluster::Create(sname, i, this);
60	  }
61	
62	  // create L3 cache; when L3 is enabled it is the LLC, otherwise it is a
63	  // transparent bypass arbiter and the L2 (or L1) is the LLC.
64	  l3cache_ = Cache::Create("l3cache", Cache::Config{
65	    !VX_CFG_L3_ENABLED,
66	    log2ceil(VX_CFG_L3_SIZE),  // C
67	    log2ceil(VX_CFG_L3_LINE_SIZE),   // L
68	    log2ceil(VX_CFG_L3_SECTOR_SIZE), // S
69	    log2ceil(VX_CFG_L2_SECTOR_SIZE), // W
70	    log2ceil(VX_CFG_L3_NUM_WAYS),    // A
71	    log2ceil(VX_CFG_L3_NUM_BANKS),   // B
72	    VX_CFG_XLEN,                     // address bits
73	    VX_CFG_L3_NUM_REQS,              // request size
74	    VX_CFG_L3_MEM_PORTS,             // memory ports
75	    VX_CFG_L3_WRITEBACK,             // write-back
76	    false,                    // write response
77	    VX_CFG_L3_MSHR_SIZE,             // mshr size
78	    VX_CFG_L3_LATENCY,               // pipeline latency
79	    VX_CFG_L3_REPL_POLICY,           // replacement policy
80	    VX_CFG_L3_ENABLED != 0,          // is_llc when L3 is the LLC
81	    }
82	  );
83	
84	#if VX_CFG_EXT_A_ENABLED
85	  // Build-time invariant: every cache above the LLC must be write-through.
86	  // A write-back intermediate could absorb a store without the LLC seeing it;
87	  // a later SC on the same line would spuriously succeed (RVA permits
88	  // spurious failure, not spurious success).
89	#if VX_CFG_L3_ENABLED
90	  static_assert(!VX_CFG_DCACHE_WRITEBACK, "AMO requires write-through L1 (VX_CFG_DCACHE_WRITEBACK=0) when L3 is the LLC");
91	  static_assert(!VX_CFG_L2_WRITEBACK,     "AMO requires write-through L2 (VX_CFG_L2_WRITEBACK=0) when L3 is the LLC");
92	#elif VX_CFG_L2_ENABLED
93	  static_assert(!VX_CFG_DCACHE_WRITEBACK, "AMO requires write-through L1 (VX_CFG_DCACHE_WRITEBACK=0) when L2 is the LLC");
94	  // L1 is unconstrained when L1 itself is the LLC.
95	#endif
96	
97	  // Non-LLC AMO passthrough: AmoProbe entries probe-and-invalidate the local
98	  // line then forward via mem_req_out tagged with AMO_PASSTHRU_TAG_FLAG so
99	  // the response routes back to core_rsp_out without installing a fill.
100	  // L1-only builds keep the dcache as the LLC and never enter this path.
101	#endif
102	
103	  // connect L3 core interfaces
104	  for (uint32_t i = 0; i < VX_CFG_NUM_CLUSTERS; ++i) {
105	    for (uint32_t j = 0; j < VX_CFG_L2_MEM_PORTS; ++j) {
106	      clusters_.at(i)->mem_req_out.at(j).bind(&l3cache_->core_req_in.at(i * VX_CFG_L2_MEM_PORTS + j));
107	      l3cache_->core_rsp_out.at(i * VX_CFG_L2_MEM_PORTS + j).bind(&clusters_.at(i)->mem_rsp_in.at(j));
108	    }
109	  }
110	
111	  // connect L3 memory interfaces
112	  for (uint32_t i = 0; i < VX_CFG_L3_MEM_PORTS; ++i) {
113	    l3cache_->mem_req_out.at(i).bind(&memsim_->mem_req_in.at(i));
114	    memsim_->mem_rsp_out.at(i).bind(&l3cache_->mem_rsp_in.at(i));
115	  }
116	
117	  // set up memory profiling
118	  for (uint32_t i = 0; i < VX_CFG_L3_MEM_PORTS; ++i) {
119	    memsim_->mem_req_in.at(i).tx_callback([&](const MemReq& req, uint64_t cycle){
120	      __unused (cycle);
121	      perf_mem_reads_  += !req.is_write();
122	      perf_mem_writes_ += req.is_write();
123	      perf_mem_pending_reads_ += !req.is_write();
124	    });
125	    memsim_->mem_rsp_out.at(i).tx_callback([&](const MemRsp&, uint64_t cycle){
126	      __unused (cycle);
127	      --perf_mem_pending_reads_;
128	    });
129	  }
130	
131	#ifndef NDEBUG
132	  // dump device configuration
133	  std::cout << "CONFIGS:"
134	            << " num_threads=" << VX_CFG_NUM_THREADS
135	            << ", num_warps=" << VX_CFG_NUM_WARPS
136	            << ", num_cores=" << VX_CFG_NUM_CORES
137	            << ", num_clusters=" << VX_CFG_NUM_CLUSTERS
138	            << ", socket_size=" << VX_CFG_SOCKET_SIZE
139	            << ", local_mem_base=0x" << std::hex << VX_MEM_LMEM_BASE_ADDR << std::dec
140	            << ", num_barriers=" << VX_CFG_NUM_BARRIERS
141	            << std::endl;
142	#endif
143	  // reset the device
144	  this->reset();
145	}
