156	void ProcessorImpl::flush_caches() {
157	  // Cache hierarchy is drained inside-out: issue all L1 flush_begin() calls
158	  // up-front so icache, dcache, and graphics caches flush in parallel, then
159	  // tick until all surfaces report flush_done().
160	
161	  // L1 surfaces: dcache + icache + graphics caches.
162	  // Write-through surfaces early-exit in Cache::flush_begin().
163	  for (auto& cluster : clusters_) {
164	    cluster->dcache_flush_begin();
165	    cluster->icache_flush_begin();
166	#ifdef VX_CFG_EXT_TEX_ENABLE
167	    cluster->tcache_flush_begin();
168	#endif
169	#ifdef VX_CFG_EXT_RASTER_ENABLE
170	    cluster->rcache_flush_begin();
171	#endif
172	#ifdef VX_CFG_EXT_OM_ENABLE
173	    cluster->ocache_flush_begin();
174	#endif
175	#ifdef VX_CFG_EXT_RTU_ENABLE
176	    cluster->rtcache_flush_begin();
177	#endif
178	  }
179	  while (true) {
180	    bool all_done = true;
181	    for (auto& cluster : clusters_) {
182	      if (!cluster->dcache_flush_done()) { all_done = false; break; }
183	      if (!cluster->icache_flush_done()) { all_done = false; break; }
184	#ifdef VX_CFG_EXT_TEX_ENABLE
185	      if (!cluster->tcache_flush_done()) { all_done = false; break; }
186	#endif
187	#ifdef VX_CFG_EXT_RASTER_ENABLE
188	      if (!cluster->rcache_flush_done()) { all_done = false; break; }
189	#endif
190	#ifdef VX_CFG_EXT_OM_ENABLE
191	      if (!cluster->ocache_flush_done()) { all_done = false; break; }
192	#endif
193	#ifdef VX_CFG_EXT_RTU_ENABLE
194	      if (!cluster->rtcache_flush_done()) { all_done = false; break; }
195	#endif
196	    }
197	    if (all_done && SimChannelBase::inflight_count() == 0)
198	      break;
199	    SimPlatform::instance().tick();
200	  }
201	
202	  // L2 caches.
203	  for (auto& cluster : clusters_) {
204	    cluster->l2_flush_begin();
205	  }
206	  while (true) {
207	    bool all_done = true;
208	    for (auto& cluster : clusters_) {
209	      if (!cluster->l2_flush_done()) { all_done = false; break; }
210	    }
211	    if (all_done && SimChannelBase::inflight_count() == 0)
212	      break;
213	    SimPlatform::instance().tick();
214	  }
215	
216	  // L3 cache (single instance at processor level).
217	  l3cache_->flush_begin();
218	  while (!l3cache_->flush_done() || SimChannelBase::inflight_count() != 0) {
219	    SimPlatform::instance().tick();
220	  }
221	}
222	
223	int ProcessorImpl::run() {
224	  this->reset();
225	  kmu_->start();
226	  this->forward_delegated_launch();
227	
228	  bool done;
229	  int exitcode = 0;
230	  do {
231	    SimPlatform::instance().tick();
232	    bool any_running = false;
233	    for (auto cluster : clusters_) {
234	      if (cluster->running()) {
235	        any_running = true;
236	      } else {
237	        exitcode |= cluster->get_exitcode();
238	      }
239	    }
240	    // Stop only when cores are idle AND no channel still carries an
241	    // undelivered packet. Cache pipelines wrap a SimChannel inside TFifo,
242	    // so cache-pipe state (and any in-flight cache→memory writethrough)
243	    // shows up in the same counter — no per-module busy reporting needed.
244	    done = !any_running && (SimChannelBase::inflight_count() == 0);
245	    perf_mem_latency_ += perf_mem_pending_reads_;
246	  } while (!done);
247	
248	  return exitcode;
249	}
