251	void ProcessorImpl::forward_delegated_launch() {
252	#ifdef VX_CFG_EXT_RASTER_ENABLE
253	  if (kmu_->launch_delegated()) {
254	    for (auto& cluster : clusters_) {
255	      cluster->raster_core()->frame_kick();
256	    }
257	  }
258	#endif
259	}
