270	bool ProcessorImpl::cycle() {
271	  // Lazy first-call init mirrors run()'s top-of-loop sequence so the
272	  // external driver doesn't need to choreograph reset + kmu start
273	  // separately. reset() clears is_cycle_initialized_ so a back-to-back
274	  // kernel launch re-dispatches.
275	  if (!is_cycle_initialized_) {
276	    this->reset();
277	    kmu_->start();
278	    this->forward_delegated_launch();
279	    is_cycle_initialized_ = true;
280	  }
281	  SimPlatform::instance().tick();
282	  perf_mem_latency_ += perf_mem_pending_reads_;
283	  return this->any_running();
284	}
