286	int ProcessorImpl::dcr_write(uint32_t addr, uint32_t value) {
287	  // KMU DCRs route to the KMU and are not broadcast to cores.
288	  bool is_kmu_dcr = (addr >= VX_DCR_KMU_STATE_BEGIN && addr < VX_DCR_KMU_STATE_END);
289	  if (is_kmu_dcr) {
290	    kmu_->dcr_write(addr, value);
291	    return 0;
292	  }
293	  for (auto& cluster : clusters_) {
294	    int ret = cluster->dcr_write(addr, value);
295	    if (ret != 0)
296	      return ret;
297	  }
298	  return 0;
299	}
