301	int ProcessorImpl::dcr_read(uint32_t addr, uint32_t tag, uint32_t* value) {
302	  if (addr == VX_DCR_BASE_CACHE_FLUSH) {
303	    // Drain dirty cache lines to DRAM before the host reads back results.
304	    // After flush_caches() returns every dirty line has reached memsim_'s
305	    // backing RAM.
306	    this->flush_caches();
307	    *value = 0;
308	    return 0;
309	  }
310	  for (auto& cluster : clusters_) {
311	    int ret = cluster->dcr_read(addr, tag, value);
312	    if (ret != 0)
313	      return ret;
314	  }
315	  return 0;
316	}
